            + 'Node-RED through start-nodered.ps1, which asks for the '
            + 'password without echoing it.', msg);
        return null;
    }
    return 'Basic ' + Buffer.from(u + ':' + p).toString('base64');
}

if (msg.statusCode === 200 && msg.payload) {
    msg.cadBuffer = msg.payload;
} else {
    node.warn('CAD download incomplete: ' + msg.statusCode);
    msg.cadBuffer = null;
}

if (msg.previewUrl) {
    msg.url = msg.previewUrl;
    msg.headers = { 'Authorization': plmAuth(),  'Accept': '*/*' };
    return msg;
}

msg.previewBuffer = null;
msg.topic = 'doc';
msg.payload = {
    docData: msg.docMetadata,
    cadBuffer: msg.cadBuffer,
    cadName: msg.cadName,
    previewBuffer: null,
    previewName: msg.previewName
};
return msg;

if (msg.statusCode === 200 && msg.payload) {
    msg.previewBuffer = msg.payload;
} else {
    node.warn('Preview Download unvollständig: ' + msg.statusCode);
    msg.previewBuffer = null;
}

msg.topic = 'doc';
msg.payload = {
    docData: msg.docMetadata,
    cadBuffer: msg.cadBuffer,
    fileName: msg.cadName,
    previewBuffer: msg.previewBuffer,
    previewName: msg.previewName
};
return msg;

const bom      = [];
const docRes   = msg.payload||{};
const part     = msg.partData;

const BASE_PATH   = env.get('SDI_PLM_BASE_SHELL') || '';
const OUTPUT_PATH = env.get('SDI_PLM_OUTPUT') || '';
const PYTHON_SCRIPT = env.get('SDI_PLM_SCRIPT') || '';

const fs   = global.get('fs');
const path = global.get('path');

// Working directory from the environment, with a fallback next to the
// working directory of Node-RED. A fixed Windows path stood here before:
// on Linux and macOS the flow failed, and on Windows the intermediate
// files ended up outside the project.
const JOB = (env.get('SDI_PLM_JOBDIR') || 'jobs') + '/' + msg.jobId;
fs.mkdirSync(JOB, { recursive: true });
const DATA_JSON = JOB + "/data.json";
const FILE_BIN = JOB + "/cad.bin";
const PREVIEW_BIN = JOB + "/preview.jpg";

const cadBuf = docRes.cadBuffer;
if(cadBuf && cadBuf.length > 0){
  try { fs.writeFileSync(FILE_BIN, cadBuf); node.warn('CAD binary written: ' + cadBuf.length + ' bytes'); }
  catch(e) { node.warn('Writing the CAD file failed: ' + e.message); }
}

const prevBuf = docRes.previewBuffer;
if(prevBuf && prevBuf.length > 0){
  try { fs.writeFileSync(PREVIEW_BIN, prevBuf); node.warn('Preview binary written: ' + prevBuf.length + ' bytes'); }
  catch(e) { node.warn('Writing the preview failed: ' + e.message); }
}

let maxBomCsv = '';
try {
    const csvPath = BASE_PATH.replace(/\//g,'\\') + '\\aasx\\files\\Produktstruktur_MaxBOM_TRACEpen_Kugelschreiber.CSV';
    if (fs.existsSync(csvPath)) {
        maxBomCsv = fs.readFileSync(csvPath, 'latin1');
        node.warn('MaxBOM CSV loaded: ' + csvPath.replace(/.*[\\/]/, ''));
    }
} catch(e) { node.warn('MaxBOM CSV not loaded: ' + e.message); }

const partNameSafe = (part && part.name) ? part.name : '';
const templateXmlPath = partNameSafe
    ? OUTPUT_PATH + '/' + partNameSafe + '/aasx/' + partNameSafe + '/' + partNameSafe + '.aas.xml'
    : '';
node.warn('Template: ' + templateXmlPath.replace(/.*[\\/]/, ''));

const data = {
  part: part,
  bomItems: bom,
  docData: docRes.docData||null,
  fileName: docRes.fileName||"model.sldasm",
  previewName: docRes.previewName||"preview.jpg",
  basePath: BASE_PATH,
  outputPath: OUTPUT_PATH,
  cadBinPath: (cadBuf&&cadBuf.length>0) ? FILE_BIN : null,
  previewBinPath: (prevBuf&&prevBuf.length>0) ? PREVIEW_BIN : null,
  maxBomCsv: maxBomCsv,
  templateXmlPath: templateXmlPath,
};
try{
  fs.writeFileSync(DATA_JSON, JSON.stringify(data,null,2),'utf8');
  node.warn('JSON written: '+DATA_JSON);
}catch(e){
  node.error('Writing the JSON failed: '+e.message);
  return null;
}

msg.pythonScript = PYTHON_SCRIPT;
msg.dataJson     = DATA_JSON;
msg.outputPath   = OUTPUT_PATH;
msg.payload      = 'python "' + PYTHON_SCRIPT + '" "' + DATA_JSON + '"';
// Report the program name and the job only - the full path does not belong
// in the log, it is held in the configuration.
node.warn('Starting ' + String(msg.payload).replace(/.*[\\/]/, '')
        .replace(/".*/, '') + ' for job ' + (msg.jobId || '?'));
return msg;

const out = typeof msg.payload==='string' ? msg.payload : JSON.stringify(msg.payload);
if(out && out.trim()) node.warn('Python output: '+out.substring(0,2000));
msg.payload = {
  status: msg.rc===0||out.includes('FERTIG') ? 'OK' : 'CHECK',
  pythonOutput: out,
  outputPath: msg.outputPath||'?',
};
return msg;

const d = msg.basicData;
const a = msg.payload;
if(msg.statusCode!==200){
    // Pass the address and the start of the answer along: without them a
    // fault of the PLM server cannot be told apart from wrong credentials
    // or an unknown part number.
    const anfang = typeof msg.payload === 'string'
        ? msg.payload.substring(0, 200)
        : JSON.stringify(msg.payload || '').substring(0, 200);
    node.error('Part HTTP ' + msg.statusCode + ' at ' + msg.url
             + ' | answer: ' + anfang, msg);
    return null;
}
const rel = (d['system:relships']&&d['system:relships']['relships'])||{};
msg.partData = {
  name:             d['benennung']||null,
  articleNumber:    d['teilenummer']||null,
  erpNumber:        d['component_materialnr_erp']||null,
  status:           d['component_status_name']||null,
  navigationId:     d['system:navigation_id']||null,
  uiLink:           d['system:ui_link']||null,
  quantity:         d['menge'] || null,
  unit:             d['mengeneinheit']||null,
  category:         d['t_kategorie']||null,
  weight:           d['techdaten'].split(', ')[1] || null,
  material:         a['name'] || null,
};
msg.relDocsUrl = rel['Documents']||null;
node.warn('Part ok: '+msg.partData.name);
msg.jobId = msg.partData.articleNumber + "_" + Date.now();
return msg;
